shape: {
points: calculatePoints(initialDegree),
transition: 'points'
},
extra: {
degree: nextDegree
},
// 让 echarts 对 `extra.degree` 进行插值，然后基于
// `extra.degree` 来计算动画中每一帧时的 polygon 形状。
transition: 'extra',
